refentry.refsect1:
&reftitle.description;

 public boolYaf_Request_Abstract::isDispatched


Détermine si la requête a été distribuée.

  &reftitle.examples;

   Exemple avec Yaf_Request_Abstract::isDispatched


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        // Arrête la boucle de distribution, aucune autre action ne sera distribuée
        $this->getRequest()->setDispatched();

        var_dump($this->getRequest()->isDispatched());
    }
}
?>

   &example.outputs.similar;


bool(true)
